/** Copies only a stopped private fixture whose full16A/J objectives were already earned natively. */
public final class MasterForestryRuntimeTests {
 public static void realSixSpeciesAndReplacementCycles(GameTestHelper h)throws Exception{new Walk(h).start();}
 static final class Walk {
  final GameTestHelper h;final ServerLevel level;final ServerPlayer p;final ConstructionStore.Project lodge;final BlockPos root;final ItemStack originalHand;int tree;
  final Item[] saplings={Items.OAK_SAPLING,Items.BIRCH_SAPLING,Items.SPRUCE_SAPLING,Items.JUNGLE_SAPLING,Items.ACACIA_SAPLING,Items.CHERRY_SAPLING};
  Walk(GameTestHelper h)throws Exception{this.h=h;level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(200);lodge=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.LUMBERJACK.buildingId())).findFirst().orElseThrow();p=ClaimRuntimeTests.vanillaPlayer(level,lodge.owner(),lodge.ownerName());originalHand=p.getMainHandItem().copy();root=lodge.origin().offset(0,0,90);}
  void guard(Runnable action){try{action.run();}catch(Exception failure){h.fail(failure.toString());}}
  void move(BlockPos at){p.moveTo(at.getX()+2.5,at.getY()+1,at.getZ()+2.5);level.getChunkSource().move(p);}
  void use(BlockPos clicked){p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(clicked).add(0,.5,0),Direction.UP,clicked,false));}
  void start()throws Exception{
   var roster=CommerceService.store(p.server).professions(p.getUUID());h.assertTrue(roster.isActive(Profession.LUMBERJACK)&&roster.progressBand(Profession.LUMBERJACK)==ProfessionRank.MASTER,"Original earned full16proofs open Master trials without injected rank");
   var bounds=ConstructionService.bounds(lodge);for(int x=((int)bounds.minX)>>4;x<=((int)bounds.maxX)>>4;x++)for(int z=((int)bounds.minZ)>>4;z<=((int)bounds.maxZ)>>4;z++)level.getChunk(x,z);
   if(roster.track(Profession.LUMBERJACK).completedQuestIds().contains("kingdom_smp:lumberjack/m01")){h.runAfterDelay(40,()->guard(()->{deliverTimber();var restored=CommerceService.store(p.server).professions(p.getUUID());h.assertTrue(restored.track(Profession.LUMBERJACK).completedQuestIds().contains("kingdom_smp:lumberjack/m05")&&restored.track(Profession.LUMBERJACK).xp()==3300&&restored.track(Profession.LUMBERJACK).completedQuestIds().size()==19,"Original19earned3300XPrestore");h.assertTrue(ConstructionService.structureIntact(level,lodge)&&level.getEntity(lodge.npc()) instanceof com.mohymods.kingdomsmp.npc.ReeveEntity,"Original Lodge and Brenna restore");h.assertTrue(TreeQuestService.count(p,"kingdom_smp:lumberjack/m01")==48&&TreeQuestService.count(p,"kingdom_smp:lumberjack/m05")>=47,"Exact species/renewal provenance survives restart");com.mojang.logging.LogUtils.getLogger().info("MASTER_FORESTRY_RESTART_PASSED: original19earned3300XP/native six-species48maturity and47replacement cycles/original Lodge and Brenna/receipts restore without replay");h.succeed();}));return;}
   h.assertTrue(roster.track(Profession.LUMBERJACK).xp()==2400&&roster.track(Profession.LUMBERJACK).completedQuestIds().size()==16,"Start from actual full16A/Jreceipt, not an artificial Master roster");DimensionTravelRuntimeTests.seed(p.server,5);h.assertTrue(!ProfessionQuestService.ready(p,"kingdom_smp:lumberjack/m01"),"Tier5cannot use Tier6Master woodland");DimensionTravelRuntimeTests.seed(p.server,6);
   for(int x=(root.getX()-14)>>4;x<=(root.getX()+14)>>4;x++)for(int z=(root.getZ()-14)>>4;z<=(root.getZ()+14)>>4;z++){var at=new BlockPos(x*16,root.getY(),z*16);level.getChunk(x,z);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);}plant();
  }
  void plant(){guard(()->{for(var at:BlockPos.betweenClosed(root.offset(-12,0,-12),root.offset(12,40,12)))level.setBlock(at,Blocks.AIR.defaultBlockState(),18);for(var at:BlockPos.betweenClosed(root.offset(-13,-1,-13),root.offset(13,-1,13)))level.setBlock(at,Blocks.GRASS_BLOCK.defaultBlockState(),18);move(root);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(saplings[tree/8]));use(root.below());h.assertTrue(p.getMainHandItem().isEmpty()&&level.getBlockState(root).getBlock() instanceof SaplingBlock,"Actual authorized native sapling placement consumes the private supplied sapling");h.runAfterDelay(3,()->guard(this::grow));});}
  void grow(){move(root);var source=TreeSavedData.get(p.server).evidence().plantAt(level.dimension().location().toString(),root).orElseThrow();h.assertTrue(source.band()==ProfessionRank.MASTER&&source.player().equals(p.getUUID()),"Saved genuine planter/band, not client counts");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BONE_MEAL,64));for(int n=0;n<64&&level.getBlockState(root).getBlock() instanceof SaplingBlock;n++)use(root);h.assertTrue(!(level.getBlockState(root).getBlock() instanceof SaplingBlock),"Actual successful native tree feature, using real consumed bonemeal");h.runAfterDelay(3,()->guard(this::harvest));}
  void harvest(){var data=TreeSavedData.get(p.server).evidence();int logs=0;for(var at:BlockPos.betweenClosed(root.offset(-12,0,-12),root.offset(12,40,12)))if(TreeLifecycle.species(level.getBlockState(at))!=null){h.assertTrue(data.logAt(level.dimension().location().toString(),at).isPresent(),"Only actual native feature logs supply provenance");move(at);h.assertTrue(p.gameMode.destroyBlock(at),"Actual native player log removal");logs++;}h.assertTrue(logs>0,"A genuine tree was harvested");tree++;if(tree<48){h.runAfterDelay(3,this::plant);return;}finish();}
  void deliverTimber(){try{
   var store=CommerceService.store(p.server);if(store.professions(p.getUUID()).track(Profession.LUMBERJACK).completedQuestIds().contains(MasterTimberDelivery.QUEST))return;var proof=TreeSavedData.get(p.server).evidence().evidence();Map<String,Integer> counts=new HashMap<>();for(var kind:TreeEvidence.SPECIES)counts.put(kind,proof.count(p.getUUID(),ProfessionRank.MASTER,kind));var supplied=MasterTimberDelivery.select(counts,counts,256);for(var entry:supplied.entrySet()){var item=net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.withDefaultNamespace(entry.getKey()+"_log"));int left=entry.getValue();while(left>0){int batch=Math.min(64,left);h.assertTrue(p.getInventory().add(new ItemStack(item,batch)),"Explicit private plain timber inputs fit; original native harvest counters are never injected");left-=batch;}}
   var home=lodge.origin().offset(BlueprintRegistry.get(lodge.blueprint(),1).home());p.moveTo(home.getX()+.5,home.getY(),home.getZ()-1.5);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(lodge.npc()));int before=timberCount();var q=ProfessionService.review(p,"materials:"+MasterTimberDelivery.QUEST);var original=p.getInventory().getItem(0).copy();p.getInventory().setItem(0,new ItemStack(Items.DIRT));boolean denied=false;try{ProfessionService.confirm(p,q.nonce());}catch(IllegalStateException expected){denied=true;}p.getInventory().setItem(0,original);h.assertTrue(denied&&store.professions(p.getUUID()).track(Profession.LUMBERJACK).xp()==3000,"Stale inventory cannot consume timber or award XP");q=ProfessionService.review(p,"materials:"+MasterTimberDelivery.QUEST);ProfessionService.confirm(p,q.nonce());h.assertTrue(timberCount()==before-256&&store.professions(p.getUUID()).track(Profession.LUMBERJACK).xp()==3300,"Exactly256actual plain logs permanently consumed for300XPonce with four native species quotas");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MASTER_TIMBER_NATIVE_PASSED: original real native Master harvest evidence and actual256plain log inventory across4species, changed inventory refusal, reviewed native consume receipt/300XPonce to19earned3300XP; supplied physical inputs only, no harvest/profession proof injection");com.mojang.logging.LogUtils.getLogger().info("MASTER_FORESTRY_NATIVE_PASSED: previously earned native48mature/47replacement proofs plus actual physical timber receipt and original Lodge/Brenna");
  }catch(Exception failure){throw new IllegalStateException(failure);}}
  int timberCount(){int count=0;for(int i=0;i<36;i++){var stack=p.getInventory().getItem(i);if(!stack.isEmpty()&&MasterTimberDelivery.species(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(stack.getItem()).toString())!=null&&ItemStack.isSameItemSameComponents(stack,new ItemStack(stack.getItem())))count+=stack.getCount();}return count;}
  void finish(){try{h.assertTrue(TreeQuestService.count(p,"kingdom_smp:lumberjack/m01")==48,"Six species each contribute eight distinct mature trees");h.assertTrue(TreeQuestService.count(p,"kingdom_smp:lumberjack/m05")>=47,"Only linked replacement growth plus actual harvest produces renewal cycles");var at=lodge.origin().offset(BlueprintRegistry.get(lodge.blueprint(),1).home());p.moveTo(at.getX()+.5,at.getY(),at.getZ()-1.5);CommerceService.openResident(p,(com.mohymods.kingdomsmp.npc.ReeveEntity)level.getEntity(lodge.npc()));for(var id:List.of("kingdom_smp:lumberjack/m01","kingdom_smp:lumberjack/m05")){var q=ProfessionService.review(p,"quest:"+id);ProfessionService.confirm(p,q.nonce());}p.setItemInHand(InteractionHand.MAIN_HAND,originalHand);deliverTimber();var track=CommerceService.store(p.server).professions(p.getUUID()).track(Profession.LUMBERJACK);h.assertTrue(track.xp()==3300&&track.completedQuestIds().size()==19,"Three actual native Master proofs award900XPonce, no invented final Master rank");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("MASTER_FORESTRY_NATIVE_PASSED: prior actual full16A/J, Tier5refusal/Tier6native six species with8genuine mature trees each, real sapling/bonemeal debit/native player trunk removals/47clearing-linked replacement cycles, original Lodge/Brenna and normal Royal three awards to19earned3300XP; explicit private tier/raw inputs only");h.succeed();}catch(Exception failure){h.fail(failure.toString());}}
 }
}
